@T.prim_func
def matmul_kernel(
    A: T.Buffer((256, 131072 * 4), "float16"),
    B: T.Buffer((131072 * 4, 256), "float16"),
    C: T.Buffer((256, 256), "float16")
):
    # Define thread indices
    tx = T.thread_binding(0, 32, "threadIdx.x")
    ty = T.thread_binding(0, 32, "threadIdx.y")
    bx = T.thread_binding(0, 8, "blockIdx.x")
    by = T.thread_binding(0, 8, "blockIdx.y")

    # Shared memory for tiles
    shared_A = T.alloc_shared((32, 1024), "float16")
    shared_B = T.alloc_shared((1024, 32), "float16")

    # Initialize accumulator
    acc = T.alloc_local((32, 32), "float32")

    # Initialize accumulator to zero
    for i in range(32):
        for j in range(32):
            acc[i, j] = 0.0

    # Loop over tiles
    for tile_idx in range(131072 * 4 // 1024):
        # Load tile of A into shared memory
        for i in range(32):
            for k in range(1024):
                shared_A[i, k] = A[bx * 32 + i, tile_idx * 1024 + k]

        # Load tile of B into shared memory
        for k in range(1024):
